Cluster Members:
[
  {
    "name": "CONCLUDES_WITH_FINAL_ANSWER",
    "definition": "The reasoning presents the definitive final result of the task, connects it to the supporting evidence chain (and, where applicable, to the produced output artifact), and asserts that the task is complete.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The agent text presenting the final result together with its supporting justification and a completion claim."
      }
    ],
    "assertion_conditions": [
      "The reasoning presents a specific final value or result as the answer to the task.",
      "The reasoning links that result to identifiable supporting evidence, such as prior observations, and to any produced output artifact when one was required.",
      "The reasoning explicitly states that the task is complete or finished."
    ],
    "exclusion_conditions": [
      "The reasoning is intermediate, exploratory, or tentative about the result.",
      "No final value or result is stated.",
      "The reasoning only describes steps or plans without asserting completion.",
      "The stated result is presented only as a candidate still subject to further verification."
    ]
  },
  {
    "name": "ASSESSES_REQUIREMENT_COMPLETION",
    "definition": "The reasoning evaluates the satisfaction status of multiple stated requirements or deliverables by explicitly mapping each to supporting evidence or an explicit satisfied/unsatisfied judgment, rather than issuing a single undifferentiated completion claim.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning that enumerates requirements or deliverables and assesses their completion status."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least two distinct requirements or deliverables.",
      "For each identified requirement or deliverable, the reasoning states a satisfaction status, supporting evidence, or an explicit judgment of completion."
    ],
    "exclusion_conditions": [
      "The reasoning gives only a general completion claim without per-requirement assessment.",
      "The reasoning merely lists requirements without indicating whether each is satisfied.",
      "The reasoning evaluates only a single requirement without a multi-requirement assessment."
    ]
  },
  {
    "name": "DECLARES_TASK_COMPLETION",
    "definition": "The reasoning asserts that the task as a whole is complete, with its stated requirements or deliverables satisfied and verified, rather than reporting only a single intermediate check, an individual deliverable, or remaining work.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that declares overall completion of the task and its requirements or deliverables."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly states that the task, or all of its stated requirements or deliverables, is complete, finished, satisfied, or verified.",
      "The completion assertion covers the task as a whole rather than a single intermediate check, probe, or partial step."
    ],
    "exclusion_conditions": [
      "The reasoning only plans future work or reports partial progress with remaining work outstanding.",
      "The reasoning reports a single check result or the status of a single deliverable without concluding that the overall task is complete.",
      "The reasoning presents one final value for a single-question task together with its supporting evidence chain, without making an aggregate completion claim about multiple requirements or deliverables.",
      "The reasoning's own content acknowledges that a required item remains unverified, failing, or undone, contradicting the completion claim."
    ]
  },
  {
    "name": "PREDICTS_EXPECTED_OUTCOME",
    "definition": "The reasoning computes and states concrete expected result values, entities, or records that the eventual solution or implementation should produce, establishing a reference against which a later implementation or its output can be validated.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text enumerating concrete expected outputs for the eventual solution."
      }
    ],
    "assertion_conditions": [
      "The reasoning enumerates specific expected output values, entities, records, or rows derived from domain facts.",
      "The predicted result is presented as what a correct solution or implementation should yield.",
      "The expectation is concrete enough to serve as a reference for later validation."
    ],
    "exclusion_conditions": [
      "The reasoning only states a general goal or success criteria without concrete expected values.",
      "The stated expectations are not derived from domain facts or are too vague to validate against.",
      "The reasoning merely restates an observed result as already obtained rather than predicting what a future solution should produce."
    ]
  }
]

